WFJ.Data.add("quest", {
  [81570] = { "A Jarl serve una lama", "Porta uno ⟦Moonsteel Broadsword=Spadone d'Acciaio Lunare⟧ a Jarl ad ⟦Dustwallow Marsh=Acquemorte⟧.", "Ho da tagliare. Non posso dirti cosa taglierò, ma... mi serve una lama. Una certa lama...\n\nAlcuni la chiamano spadone d'acciaio lunare. Io la chiamo falce.\n\nMi aiuti? Forse la trovi in città, forse parli con un fabbro e te la fa su misura.\n\nMa non dormirci sopra. Quello che devo tagliare non si conserva per sempre...", nil, nil, 0x83fbbd68, 0xb3fd6755, 0xb542ec67, nil, nil, "...mm" },
  [81730] = { "Missione di ⟦Duskwood=Boscovespro⟧ I: sconfiggere i worgen", "Sconfiggi 10 Nightmare Runner e 10 Nightmare Weaver nell'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, nel Frutteto Marcescente, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo nel Frutteto Marcescente. Sconfiggi i worgen che trovi lì e torna da me.", nil, nil, 0x0cf2dd2a, 0xe1a2c79f, 0x982208ee, nil, nil, "...mm" },
  [81731] = { "Missione di ⟦Duskwood=Boscovespro⟧ II: sconfiggere gli ogre", "Sconfiggi 3 Deranged Ogre e 3 Demented Fire Weaver nell'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, al Tumulo degli Ogre Vul'Gol, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo al Tumulo degli Ogre Vul'Gol. Sconfiggi gli ogre che trovi lì e torna da me.", nil, nil, 0x3bc05c8c, 0x4327bcd2, 0xb8acdaee, nil, nil, "...mm" },
  [81732] = { "Missione di ⟦Duskwood=Boscovespro⟧ III: sconfiggere i dragoidi", "Sconfiggi 3 Wyrmkin Terrorwalker e 10 Nightterror Whelp nell'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, alla Yorgen Farmstead, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo alla Yorgen Farmstead. Sconfiggi i dragoidi che trovi lì e torna da me.", nil, nil, 0x4611b618, 0x85d50f0d, 0x63fabb72, nil, nil, "...mm" },
  [81733] = { "Missione di ⟦Duskwood=Boscovespro⟧ IV: informazioni sugli ogre", "Raccogli informazioni dal sorvegliante del Sogno Thalinar nell'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, nel profondo del Tumulo degli Ogre Vul'Gol, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo al Tumulo degli Ogre Vul'Gol. Fatti consegnare un rapporto informativo dal sorvegliante del Sogno Thalinar e torna da me.", nil, nil, 0xeb1f89b8, 0x784d4e43, 0x6d3bf7e9, nil, nil, "...mm" },
