  [81738] = { "Missione di ⟦Duskwood=Boscovespro⟧ IX: recuperare l'uovo di drago", "Recupera un ⟦Unhatched Green Dragon Egg=Uovo di Drago Verde Non Schiuso⟧ nell'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, alla Yorgen Farmstead, vicino al grosso ceppo nei campi, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo alla Yorgen Farmstead. Recupera un ⟦Unhatched Green Dragon Egg=Uovo di Drago Verde Non Schiuso⟧ e consegnamelo.", nil, nil, 0x3941eba9, 0x03540759, 0xd172b113, nil, nil, "...mm" },
  [81739] = { "Missione di ⟦Duskwood=Boscovespro⟧ X: ⟦Nightmare Moss=Muschio dell'Incubo⟧", "Raccogli 10 ⟦Nightmare Moss=Muschio dell'Incubo⟧ nelle Incursioni dell'Incubo di ⟦Duskwood=Boscovespro⟧, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raccogli del ⟦Nightmare Moss=Muschio dell'Incubo⟧ nelle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di un erborista.", nil, nil, 0x41d8371c, 0x2289c12b, 0x30adad8b, nil, nil, "...mm" },
  [81740] = { "Missione di ⟦Duskwood=Boscovespro⟧ XI: ⟦Cold Iron Ore=Minerale di Ferro Freddo⟧", "Raccogli 10 ⟦Cold Iron Ore=Minerale di Ferro Freddo⟧ nelle Incursioni dell'Incubo di ⟦Duskwood=Boscovespro⟧, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raccogli del ⟦Cold Iron Ore=Minerale di Ferro Freddo⟧ nelle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di un minatore.", nil, nil, 0xb76951d2, 0xc96ad9fc, 0x620aa8b3, nil, nil, "...mm" },
  [81741] = { "Missione di ⟦Duskwood=Boscovespro⟧ XII: ⟦Dream-Touched Dragonscale=Scaglia di Drago Toccata dal Sogno⟧", "Raccogli 10 Dream-Touched Dragonscale nelle Incursioni dell'Incubo di ⟦Duskwood=Boscovespro⟧, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raccogli delle Dream-Touched Dragonscale dai dragoidi delle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di uno scuoiatore.", nil, nil, 0xb9ecbfdc, 0xa96c76e5, 0x0f3c381b, nil, nil, "...mm" },
  [81742] = { "Missione di ⟦Duskwood=Boscovespro⟧ XIII: sconfiggere Ylanthrius", "Sconfiggi Ylanthrius nell'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, nel campo della Yorgen Farmstead, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo alla Yorgen Farmstead. Sconfiggi il drago Ylanthrius e torna da me.", nil, nil, 0x54cddfe0, 0xada241be, 0xbd679dc1, nil, nil, "...mm" },
