  [81744] = { "Missione di ⟦Duskwood=Boscovespro⟧ XV: sconfiggere Amokarok", "Sconfiggi Amokarok nell'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, in un accampamento vicino al granaio del Frutteto Marcescente, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo nel Frutteto Marcescente. Sconfiggi il capo dei worgen Amokarok e torna da me.", nil, nil, 0x3f25090f, 0x63ef6a7c, 0x451996ef, nil, nil, "...mm" },
  [81745] = { "Missione di ⟦Duskwood=Boscovespro⟧ XVI: salvare Kroll Mountainshade", "Salva Kroll Mountainshade dall'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, nella foresteria del Frutteto Marcescente, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo nel Frutteto Marcescente. Trova il druido dell'Unghia Kroll Mountainshade, che dorme lì, e scortalo al sicuro. Poi torna da me.", nil, nil, 0x24c25245, 0x2b8afb56, 0xd286b19d, nil, nil, "...mm" },
  [81746] = { "Missione di ⟦Duskwood=Boscovespro⟧ XVII: salvare Alara Grovemender", "Salva Alara Grovemender nell'Incursione dell'Incubo di ⟦Duskwood=Boscovespro⟧, nella stalla della Yorgen Farmstead, poi torna dal capitano di campo Palandar.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nel ⟦Twilight Grove=Bosco del Crepuscolo⟧ e raggiungi l'Incursione dell'Incubo alla Yorgen Farmstead. Trova la druida dell'Unghia Alara Grovemender, che dorme lì, e scortala al sicuro. Poi torna da me.", nil, nil, 0x8ffdbb57, 0xfed717a4, 0x247486e4, nil, nil, "...mm" },
