  [81774] = { "Missione di ⟦Ashenvale=Valtetra⟧ VII: recuperare il ⟦Dreamengine=Motore Onirico⟧", "Recupera il ⟦Dreamengine=Motore Onirico⟧ nell'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, dalla forgia del ⟦Warsong Lumber Camp=Campo di Taglio dei Cantaguerra⟧, poi torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo al ⟦Warsong Lumber Camp=Campo di Taglio dei Cantaguerra⟧. Recupera un potente manufatto noto come ⟦Dreamengine=Motore Onirico⟧ e consegnamelo.", nil, nil, 0xa80b3dd7, 0xb9feeac4, 0xe7ba1cfb, nil, nil, "...mm" },
  [81775] = { "Missione di ⟦Ashenvale=Valtetra⟧ VIII: recuperare la ⟦Azsharan Prophecy=Profezia di Azshara⟧", "Recupera la ⟦Azsharan Prophecy=Profezia di Azshara⟧ nell'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, dalla piccola tenda di ⟦Satyrnaar=Satirnaar⟧, poi torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo a ⟦Satyrnaar=Satirnaar⟧. Recupera una pergamena perduta nota come ⟦Azsharan Prophecy=Profezia di Azshara⟧ e consegnamela.", nil, nil, 0xbc02bae0, 0xc04078eb, 0x19dbdf62, nil, nil, "...mm" },
  [81776] = { "Missione di ⟦Ashenvale=Valtetra⟧ IX: recuperare il Dream-Touched Dragonegg", "Recupera un Dream-Touched Dragonegg nell'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, dalla rovina centrale di ⟦Forest Song=Cantaselva⟧, poi torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo a ⟦Forest Song=Cantaselva⟧. Recupera un Dream-Touched Dragonegg e consegnamelo.", nil, nil, 0xbc759dc6, 0xf57cca69, 0x90cfc82e, nil, nil, "...mm" },
  [81777] = { "Missione di ⟦Ashenvale=Valtetra⟧ X: ⟦Dreamroot=Radice Onirica⟧", "Raccogli 10 ⟦Dreamroot=Radice Onirica⟧ nelle Incursioni dell'Incubo di ⟦Ashenvale=Valtetra⟧, poi torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci distraggono qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il Portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raccogli della ⟦Dreamroot=Radice Onirica⟧ nelle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di un erborista.", nil, nil, 0x9173f4eb, 0xc716164d, 0xd031fde0, nil, nil, "...mm" },
