  [81779] = { "Missione di ⟦Ashenvale=Valtetra⟧ XII: ⟦Dream-Infused Dragonscale=Scaglia di Drago Infusa di Sogno⟧", "Raccogli 10 ⟦Dream-Infused Dragonscale=Scaglia di Drago Infusa di Sogno⟧ nelle Incursioni dell'Incubo di ⟦Ashenvale=Valtetra⟧ e torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raccogli ⟦Dream-Infused Dragonscale=Scaglia di Drago Infusa di Sogno⟧ dai dragoidi delle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di uno scuoiatore.", nil, nil, 0x9c54d398, 0xc788b851, 0xcc1417d4, nil, nil, "...mm" },
  [81780] = { "Missione di ⟦Ashenvale=Valtetra⟧ XIII: sconfiggere Larsera", "Sconfiggi Larsera nell'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, fuori dalla rovina centrale di ⟦Forest Song=Cantaselva⟧, e torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo a ⟦Forest Song=Cantaselva⟧. Sconfiggi il drago Larsera laggiù e torna da me.", nil, nil, 0x78c0fcc5, 0x0a454a44, 0xccd60905, nil, nil, "...mm" },
  [81781] = { "Missione di ⟦Ashenvale=Valtetra⟧ XIV: sconfiggere Zalius", "Sconfiggi Zalius nell'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, ai piedi dello ziggurat di ⟦Satyrnaar=Satirnaar⟧, e torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo a ⟦Forest Song=Cantaselva⟧. Sconfiggi il satiro Zalius laggiù e torna da me.", nil, nil, 0xaf2b12ec, 0x225ce7f3, 0xb58334e1, nil, nil, "...mm" },
  [81782] = { "Missione di ⟦Ashenvale=Valtetra⟧ XV: sconfiggere Shredder 9000", "Sconfiggi Shredder 9000 nell'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, vicino alle gru per il legname del ⟦Warsong Lumber Camp=Campo di Taglio dei Cantaguerra⟧, e torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo al ⟦Warsong Lumber Camp=Campo di Taglio dei Cantaguerra⟧. Sconfiggi Shredder 9000 laggiù e torna da me.", nil, nil, 0x9347ef49, 0xe472ea6a, 0x08af4104, nil, nil, "...mm" },
  [81783] = { "Missione di ⟦Ashenvale=Valtetra⟧ XVI: salvare Alyssian Windcaller", "Salva Alyssian Windcaller dall'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, ai piedi della torre di guardia del ⟦Warsong Lumber Camp=Campo di Taglio dei Cantaguerra⟧, e torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo al ⟦Warsong Lumber Camp=Campo di Taglio dei Cantaguerra⟧. Trova laggiù la druida dell'Unghia Alyssian Windcaller, addormentata, e scortala al sicuro. Poi torna da me.", nil, nil, 0x48ff0ec2, 0x819ccb25, 0xb6b4575f, nil, nil, "...mm" },
  [81784] = { "Missione di ⟦Ashenvale=Valtetra⟧ XVII: salvare Doran Dreambough", "Salva Doran Dreambough dall'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, al gazebo illuminato dalla luna di ⟦Forest Song=Cantaselva⟧, e torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo a ⟦Forest Song=Cantaselva⟧. Trova laggiù il druido dell'Unghia Doran Dreambough, addormentato, e scortalo al sicuro. Poi torna da me.", nil, nil, 0x91bc3d51, 0xc8fb6d65, 0xedcdd9e5, nil, nil, "...mm" },
  [81785] = { "Missione di ⟦Ashenvale=Valtetra⟧ XVIII: salvare Maseara Autumnmoon", "Salva Maseara Autumnmoon dall'Incursione dell'Incubo di ⟦Ashenvale=Valtetra⟧, al gruppo di tende a sud-est di ⟦Satyrnaar=Satirnaar⟧, e torna dalla capitana di campo Hannalah.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a ⟦Bough Shadow=Frondascura⟧ e raggiungi l'Incursione dell'Incubo a ⟦Satyrnaar=Satirnaar⟧. Trova laggiù la druida dell'Unghia Maseara Autumnmoon, addormentata, e scortala al sicuro. Poi torna da me.", nil, nil, 0xdf88efe5, 0xb00088f5, 0xe57aaf95, nil, nil, "...mm" },
  [81786] = { "Missione delle Entroterre I: sconfiggere i lunagufi", "Sconfiggi 20 Fallen Moonkin nell'Incursione dell'Incubo delle Entroterre, al ⟦Skulk Rock=Tumulo Strisciante⟧, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo al ⟦Skulk Rock=Tumulo Strisciante⟧. Sconfiggi i lunagufi laggiù e torna da me.", nil, nil, 0xb4097ce8, 0x4555a000, 0xa7a0ede3, nil, nil, "...mm" },
  [81787] = { "Missione delle Entroterre II: sconfiggere le tartarughe giganti", "Sconfiggi 20 Dreamwater Visejaw nell'Incursione dell'Incubo delle Entroterre, a Shaol'watha, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo a Shaol'watha. Sconfiggi le tartarughe giganti laggiù e torna da me.", nil, nil, 0x82e744a3, 0xe762dd73, 0xab9e2606, nil, nil, "...mm" },
