  [81789] = { "Missione delle Entroterre IV: informazioni sui draghi", "Raccogli informazioni da Laninar, sorvegliante del Sogno, nell'Incursione dell'Incubo delle Entroterre, presso l'arco di Agol'watha, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo ad Agol'wath. Recupera laggiù il rapporto informativo di Laninar, sorvegliante del Sogno, e torna da me.", nil, nil, 0xd007f6e9, 0xf17966af, 0x5eb8010e, nil, nil, "...mm" },
  [81817] = { "Missione delle Entroterre V: informazioni sulle tartarughe", "Raccogli informazioni da Sanathel, sorvegliante del Sogno, nell'Incursione dell'Incubo delle Entroterre, dietro il tamburo di Shaol'watha, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo a Shaol'wath. Recupera laggiù il rapporto informativo di Sanathel, sorvegliante del Sogno, e torna da me.", nil, nil, 0x05255028, 0x82e65fde, 0x690c4726, nil, nil, "...mm" },
  [81820] = { "Missione delle Entroterre VI: informazioni sui lunagufi", "Raccogli informazioni da Valori, sorvegliante del Sogno, nell'Incursione dell'Incubo delle Entroterre, presso il lago sotterraneo del ⟦Skulk Rock=Tumulo Strisciante⟧, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo al ⟦Skulk Rock=Tumulo Strisciante⟧. Recupera laggiù il rapporto informativo di Valori, sorvegliante del Sogno, e torna da me.", nil, nil, 0x28b2151f, 0xdb331edc, 0xbdf64310, nil, nil, "...mm" },
  [81826] = { "Missione delle Entroterre VII: recuperare l'⟦Star-Touched Dragonegg=Uovo di Drago Toccato dalle Stelle⟧", "Recupera un ⟦Star-Touched Dragonegg=Uovo di Drago Toccato dalle Stelle⟧ nell'Incursione dell'Incubo delle Entroterre, dalla capanna centrale di Agol'wath, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo ad Agol'watha. Recupera un ⟦Star-Touched Dragonegg=Uovo di Drago Toccato dalle Stelle⟧ e portamelo.", nil, nil, 0x194c3a46, 0xac542412, 0x7e4c5b0f, nil, nil, "...mm" },
  [81830] = { "Missione delle Entroterre VIII: recuperare la ⟦Elunar Relic=Reliquia Elunariana⟧", "Recupera una ⟦Elunar Relic=Reliquia Elunariana⟧ nell'Incursione dell'Incubo delle Entroterre, dalla sporgenza alta dentro il ⟦Skulk Rock=Tumulo Strisciante⟧, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo al ⟦Skulk Rock=Tumulo Strisciante⟧. Recupera la ⟦Elunar Relic=Reliquia Elunariana⟧ che i lunagufi hanno nascosto laggiù e portamela.", nil, nil, 0x644b94a6, 0x743be232, 0xfe215b68, nil, nil, "...mm" },
  [81832] = { "Missione delle Entroterre IX: recuperare la ⟦Dreampearl=Perla Onirica⟧", "Recupera una ⟦Dreampearl=Perla Onirica⟧ nell'Incursione dell'Incubo delle Entroterre, da una fontana a forma di serpente a Shaol'watha, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo a Shaol'watha. Recupera la ⟦Dreampearl=Perla Onirica⟧ che le tartarughe hanno nascosto laggiù e portamela.", nil, nil, 0x41d000ac, 0xcd3e26b9, 0xd2584d75, nil, nil, "...mm" },
