  [81834] = { "Missione delle Entroterre XI: ⟦Starsilver Ore=Minerale di Argento Stellare⟧", "Raccogli 10 ⟦Starsilver Ore=Minerale di Argento Stellare⟧ nelle Incursioni dell'Incubo delle Entroterre e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raccogli ⟦Starsilver Ore=Minerale di Argento Stellare⟧ nelle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di un minatore.", nil, nil, 0x5cedbd55, 0x9d5ff9d4, 0x925cf0cd, nil, nil, "...mm" },
  [81835] = { "Missione delle Entroterre XII: Starshells", "Raccogli 10 Sharshell nelle Incursioni dell'Incubo delle Entroterre e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raccogli Sharshells dalle tartarughe giganti delle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di uno scuoiatore.", nil, nil, 0xc7775122, 0xb5edc094, 0x587b3593, nil, nil, "...mm" },
