  [81838] = { "Missione delle Entroterre XIV: sconfiggere il Doomkin", "Sconfiggi il Doomkin nell'Incursione dell'Incubo delle Entroterre, sulla sporgenza profonda dentro il ⟦Skulk Rock=Tumulo Strisciante⟧, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo al ⟦Skulk Rock=Tumulo Strisciante⟧. Sconfiggi il lunagufo gigante noto come Doomkin laggiù e torna da me.", nil, nil, 0xbeede51c, 0x401b8436, 0x5d6f95a2, nil, nil, "...mm" },
  [81839] = { "Missione delle Entroterre XV: sconfiggere Ghamoo-Raja", "Sconfiggi Ghamoo-Raja nell'Incursione dell'Incubo delle Entroterre, nel cortile di Shaol'watha, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo a Shaol'watha. Sconfiggi il «re» delle tartarughe noto come Ghamoo-Raja laggiù e torna da me.", nil, nil, 0xd3647a95, 0x217f60e6, 0xabba631d, nil, nil, "...mm" },
  [81850] = { "Missione delle Entroterre XVI: salvare Elianar Shadowdrinker", "Salva Elianar Shadowdrinker dall'Incursione dell'Incubo delle Entroterre, presso la fortificazione dei troll vicino ad Agol'watha, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo ad Agol'watha. Trova laggiù il druido dell'Unghia Elianar Shadowdrinker, addormentato, e scortalo al sicuro. Poi torna da me.", nil, nil, 0xf7620e60, 0x9dd2c1e9, 0xad4a7f58, nil, nil, "...mm" },
  [81851] = { "Missione delle Entroterre XVII: salvare Serlina Starbright", "Salva Serlina Starbright dall'Incursione dell'Incubo delle Entroterre, presso la fortificazione dei troll più vicina a Shol'watha, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo a Shol'watha. Trova laggiù la druida dell'Unghia Serlina Starbright, addormentata, e scortala al sicuro. Poi torna da me.", nil, nil, 0x76878fc3, 0xd42a6778, 0x46081bbf, nil, nil, "...mm" },
  [81852] = { "Missione delle Entroterre XVIII: salvare Veanna Cloudsleeper", "Salva Veanna Cloudsleeper dall'Incursione dell'Incubo delle Entroterre, sull'amaca sopra il ⟦Skulk Rock=Tumulo Strisciante⟧, e torna dal capitano di campo Korlian.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ a Seradane e raggiungi l'Incursione dell'Incubo al ⟦Skulk Rock=Tumulo Strisciante⟧. Trova laggiù la druida dell'Unghia Veanna Cloudsleeper, addormentata, e scortala al sicuro. Poi torna da me.", nil, nil, 0x2d2af380, 0x355acd1b, 0x3bbf2476, nil, nil, "...mm" },
  [81855] = { "Missione di Feralas I: sconfiggere i figli di Cenarius", "Sconfiggi 10 Lost Daughter e 10 Vengeful Son nell'Incursione dell'Incubo di Feralas, ai Colossi Gemelli, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo ai Colossi Gemelli. Sconfiggi i figli e le figlie di Cenarius impazziti laggiù e torna da me.", nil, nil, 0x038cac6d, 0x768853ee, 0x531ad8d9, nil, nil, "...mm" },
  [81856] = { "Missione di Feralas II: sconfiggere le arpie", "Sconfiggi 10 Dreamspring Roguefeather e 10 Dreamspring Stormcaller nell'Incursione dell'Incubo di Feralas, alle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo alle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧. Sconfiggi le arpie laggiù e torna da me.", nil, nil, 0xb93ad8cf, 0xb47eda62, 0xfe618e10, nil, nil, "...mm" },
  [81857] = { "Missione di Feralas III: sconfiggere i dragoidi", "Sconfiggi 10 Frenzied Whelp e 3 Wyrmkin Berserker nell'Incursione dell'Incubo di Feralas, a Oneiros, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo a Oneiros. Sconfiggi i dragoidi laggiù e torna da me.", nil, nil, 0x68c2304b, 0x01ceba36, 0x005f7ba9, nil, nil, "...mm" },
  [81858] = { "Missione di Feralas IV: informazioni sui draghi", "Raccogli informazioni da Sheldryn, sorvegliante del Sogno, nell'Incursione dell'Incubo di Feralas, presso le rovine più a sud di Oneiros, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo a Oneiros. Recupera laggiù il rapporto informativo di Sheldryn, sorvegliante del Sogno, e torna da me.", nil, nil, 0xd3ca521c, 0x4fc5e651, 0x6ad32241, nil, nil, "...mm" },
  [81859] = { "Missione di Feralas V: informazioni sui cenariani", "Raccogli informazioni da Gorlas, sorvegliante del Sogno, nell'Incursione dell'Incubo di Feralas, vicino alla cascata dei Colossi Gemelli, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo ai Colossi Gemelli. Recupera laggiù il rapporto informativo di Gorlas, sorvegliante del Sogno, e torna da me.", nil, nil, 0xb6dd1743, 0xb270cd49, 0xb3820d4b, nil, nil, "...mm" },
  [81860] = { "Missione di Feralas VI: informazioni sulle arpie", "Raccogli informazioni da Anadelle, sorvegliante del Sogno, nell'Incursione dell'Incubo di Feralas, presso il gazebo distrutto delle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo alle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧. Recupera laggiù il rapporto informativo di Anadelle, sorvegliante del Sogno, e torna da me.", nil, nil, 0x62c1f935, 0x66676ce9, 0x288c53bb, nil, nil, "...mm" },
  [81861] = { "Missione di Feralas VII: recuperare l'⟦Moonglow Dragonegg=Uovo di Drago del Bagliore Lunare⟧", "Recupera un ⟦Moonglow Dragonegg=Uovo di Drago del Bagliore Lunare⟧ nell'Incursione dell'Incubo di Feralas, dal gazebo di Oneiros, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo a Oneiros. Recupera un ⟦Moonglow Dragonegg=Uovo di Drago del Bagliore Lunare⟧ e portamelo.", nil, nil, 0xbffa00f2, 0x167b98ea, 0x1f83a7fa, nil, nil, "...mm" },
  [81863] = { "Missione di Feralas VIII: recuperare gli appunti del custode", "Recupera gli ⟦Mad Keeper's Notes=Appunti del Custode Folle⟧ nell'Incursione dell'Incubo di Feralas, dal versante est del colosso occidentale ai Colossi Gemelli, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo ai Colossi Gemelli. Recupera gli ⟦Mad Keeper's Notes=Appunti del Custode Folle⟧ e portameli.", nil, nil, 0xf31f9314, 0xa09f8b3d, 0x7f7fb2e4, nil, nil, "...mm" },
  [81864] = { "Missione di Feralas IX: recuperare lo ⟦Harpy Screed=Scritto dell'Arpia⟧", "Recupera uno ⟦Harpy Screed=Scritto dell'Arpia⟧ nell'Incursione dell'Incubo di Feralas, dal gazebo a sud-ovest delle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo alle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧. Recupera un Harpy Screed e portamelo.", nil, nil, 0x33dde86d, 0x11dcce73, 0xcd97aa2f, nil, nil, "...mm" },
  [81865] = { "Missione di Feralas X: ⟦Moonroot=Radice Lunare⟧", "Raccogli 10 ⟦Moonroot=Radice Lunare⟧ nelle Incursioni dell'Incubo di Feralas e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raccogli ⟦Moonroot=Radice Lunare⟧ nelle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di un erborista.", nil, nil, 0xca33153b, 0xf2a31076, 0x78d1879f, nil, nil, "...mm" },
  [81866] = { "Missione di Feralas XI: ⟦Greater Moonstone=Pietraluna Superiore⟧", "Raccogli 10 ⟦Greater Moonstone=Pietraluna Superiore⟧ nelle Incursioni dell'Incubo di Feralas e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raccogli ⟦Greater Moonstone=Pietraluna Superiore⟧ nelle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di un minatore.", nil, nil, 0x2963789b, 0x33594cdc, 0x91b6d263, nil, nil, "...mm" },
  [81867] = { "Missione di Feralas XII: Greater Moondragon Scales", "Raccogli 10 Moondragon Scale nelle Incursioni dell'Incubo di Feralas e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raccogli Moondragon Scales dai dragoidi delle Incursioni dell'Incubo. Possiamo sfruttarne la magia per riparare il danno. Ti servirà l'aiuto di uno scuoiatore.", nil, nil, 0x5f666de3, 0xaa53cef7, 0x4ea05055, nil, nil, "...mm" },
  [81868] = { "Missione di Feralas XIII: sconfiggere Tyrannikus", "Sconfiggi Tyrannikus nell'Incursione dell'Incubo di Feralas, presso il tempio in rovina di Oneiros, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo a Oneiros. Sconfiggi il drago Tyrannikus laggiù e torna da me.", nil, nil, 0x0c867189, 0x0bc00c00, 0xca79d1ba, nil, nil, "...mm" },
  [81870] = { "Missione di Feralas XIV: sconfiggere Alondrius", "Sconfiggi Alondrius nell'Incursione dell'Incubo di Feralas, che pattuglia la strada ai Colossi Gemelli, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo ai Colossi Gemelli. Sconfiggi il custode del bosco Alondrius laggiù e torna da me.", nil, nil, 0xa7166c87, 0x016052fe, 0x86312dde, nil, nil, "...mm" },
  [81871] = { "Missione di Feralas XV: sconfiggere Slirena", "Sconfiggi Slirena nell'Incursione dell'Incubo di Feralas, vicino allo ziggurat delle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono impegnati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in un incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ all'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo alle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧. Sconfiggi la «regina» delle arpie Slirena laggiù e torna da me.", nil, nil, 0x8a3b136b, 0x866b0a0d, 0xeabbac63, nil, nil, "...mm" },
  [81872] = { "Missione di Feralas XVI: salvare Mellias Earthtender", "Salva Mellias Earthtender dall'Incursione dell'Incubo di Feralas presso le scale vicino al ⟦Jademir Lake=Lago Jademir⟧, a Oneiros, e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono occupati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nell'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo di Oneiros. Lì troverai il druido dell'Unghia Mellias Earthtender, addormentato: scortalo in salvo. Poi torna da me.", nil, nil, 0xc95806e6, 0x9b07b428, 0x9b0c0c0b, nil, nil, "...mm" },
  [81873] = { "Missione di Feralas XVII: salvare Nerene Brooksinger", "Salva Nerene Brooksinger dall'Incursione dell'Incubo di Feralas presso il fuoco da campo ai Colossi Gemelli e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono occupati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nell'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo ai Colossi Gemelli. Lì troverai la druida dell'Unghia Nerene Brooksinger, addormentata: scortala in salvo. Poi torna da me.", nil, nil, 0x8d91efc0, 0x06966099, 0xaf96a9fe, nil, nil, "...mm" },
  [81874] = { "Missione di Feralas XVIII: salvare Jamniss Treemender", "Salva Jamnice Treemender dall'Incursione dell'Incubo di Feralas al margine settentrionale delle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧ e torna dal capitano di campo Arunnel.", "Mentre questi demoni ci tengono occupati qui, il ⟦Emerald Dream=Sogno di Smeraldo⟧ viene corrotto e trasformato in incubo. Presto, attraversa il portale del ⟦Emerald Dream=Sogno di Smeraldo⟧ nell'⟦Dream Bough=Albero dei Sogni⟧ e raggiungi l'Incursione dell'Incubo alle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧. Lì troverai la druida dell'Unghia Jamnice Treemender, addormentata: scortala in salvo. Poi torna da me.", nil, nil, 0xf0855feb, 0xa6ed25e8, 0x240a63e6, nil, nil, "...mm" },
